	/// <summary>
	/// Wraps the unique identifier values for the <see cref="Persona"/> object.
	/// </summary>
	[Serializable]
	[CLSCompliant(true)]
	public class PersonaKey : EntityKeyBase
	{
		#region Constructors
		
		/// <summary>
		/// Initializes a new instance of the PersonaKey class.
		/// </summary>
		public PersonaKey()
		{
		}
		
		/// <summary>
		/// Initializes a new instance of the PersonaKey class.
		/// </summary>
		public PersonaKey(PersonaBase entity)
		{
			this.Entity = entity;

			#region Init Properties

			if ( entity != null )
			{
				this.PersonaId = entity.PersonaId;
			}

			#endregion
		}
		
		/// <summary>
		/// Initializes a new instance of the PersonaKey class.
		/// </summary>
		public PersonaKey(System.Guid _personaId)
		{
			#region Init Properties

			this.PersonaId = _personaId;

			#endregion
		}
		
		#endregion Constructors

		#region Properties
		
		// member variable for the Entity property
		private PersonaBase _entity;
		
		/// <summary>
		/// Gets or sets the Entity property.
		/// </summary>
		public PersonaBase Entity
		{
			get { return _entity; }
			set { _entity = value; }
		}
		
		// member variable for the PersonaId property
		private System.Guid _personaId;
		
		/// <summary>
		/// Gets or sets the PersonaId property.
		/// </summary>
		public System.Guid PersonaId
		{
			get { return _personaId; }
			set
			{
				if ( this.Entity != null )
					this.Entity.PersonaId = value;
				
				_personaId = value;
			}
		}
		
		#endregion

		#region Methods
		
		/// <summary>
		/// Reads values from the supplied <see cref="IDictionary"/> object into
		/// properties of the current object.
		/// </summary>
		/// <param name="values">An <see cref="IDictionary"/> instance that contains
		/// the key/value pairs to be used as property values.</param>
		public override void Load(IDictionary values)
		{
			#region Init Properties

			if ( values != null )
			{
				PersonaId = ( values["PersonaId"] != null ) ? (System.Guid) EntityUtil.ChangeType(values["PersonaId"], typeof(System.Guid)) : Guid.Empty;
			}

			#endregion
		}

		/// <summary>
		/// Creates a new <see cref="IDictionary"/> object and populates it
		/// with the property values of the current object.
		/// </summary>
		/// <returns>A collection of name/value pairs.</returns>
		public override IDictionary ToDictionary()
		{
			IDictionary values = new Hashtable();

			#region Init Dictionary

			values.Add("PersonaId", PersonaId);

			#endregion Init Dictionary

			return values;
		}
		
		///<summary>
		/// Returns a String that represents the current object.
		///</summary>
		public override string ToString()
		{
			return String.Format("PersonaId: {0}{1}",
								PersonaId,
								System.Environment.NewLine);
		}

		#endregion Methods
	}
	
